package com.tuap.backend.auth;
import java.util.Map; import org.slf4j.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import org.springframework.beans.factory.annotation.Autowired; import com.tuap.backend.config.EmailProperties;
@Service @ConditionalOnProperty(prefix="app.email",name="enabled",havingValue="true") public class ResendEmailService implements EmailService { private static final Logger log=LoggerFactory.getLogger(ResendEmailService.class); private final RestClient client; private final EmailProperties properties; @Autowired public ResendEmailService(RestClient.Builder builder,EmailProperties p){this(builder.baseUrl("https://api.resend.com").build(),p);} ResendEmailService(RestClient c,EmailProperties p){client=c;properties=p;} public void send(String to,String subject,String html){if(!"resend".equalsIgnoreCase(properties.getProvider())||properties.getResendApiKey().isBlank()||properties.getFrom().isBlank())throw new IllegalStateException("Email provider no configurado");try{client.post().uri("/emails").header(HttpHeaders.AUTHORIZATION,"Bearer "+properties.getResendApiKey()).contentType(MediaType.APPLICATION_JSON).body(Map.of("from",properties.getFrom(),"to",java.util.List.of(to),"subject",subject,"html",html)).retrieve().toBodilessEntity();}catch(EmailDeliveryException e){throw e;}catch(RuntimeException e){log.warn("email send failed");throw new EmailDeliveryException();}} }
